# ruff: noqa: E501
from __future__ import annotations

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>zksato Trading Control</title>
<style>
:root{--bg:#07101a;--panel:#101a27;--panel2:#142235;--line:#26384f;--text:#edf4ff;--muted:#91a4bd;--green:#43dfa2;--red:#ff6179;--cyan:#45c8ff;--amber:#ffc857}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#122944 0,#07101a 45%);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}.shell{max-width:1780px;margin:auto;padding:18px}.top{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:14px}.brand{display:flex;gap:11px;align-items:center}.logo{width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,var(--cyan),#727cff);display:grid;place-items:center;color:#07111d;font-weight:900}.brand h1{margin:0;font-size:20px}.sub,.muted{color:var(--muted)}.tiny{font-size:11px}.status,.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.pill{padding:6px 10px;border:1px solid var(--line);border-radius:999px;background:#0c1621;color:var(--muted)}.good{color:var(--green)!important}.bad{color:var(--red)!important}.warn{color:var(--amber)!important}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px}.card{background:linear-gradient(180deg,rgba(19,31,47,.98),rgba(11,20,31,.98));border:1px solid var(--line);border-radius:14px;padding:13px;box-shadow:0 12px 35px rgba(0,0,0,.2)}.metric{grid-column:span 2;min-height:92px}.metric .k{color:var(--muted);font-size:11px}.metric .v{font-size:22px;font-weight:750;margin-top:8px}.span4{grid-column:span 4}.span5{grid-column:span 5}.span6{grid-column:span 6}.span7{grid-column:span 7}.span8{grid-column:span 8}.span12{grid-column:span 12}.head{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-bottom:9px}.head h2{font-size:14px;margin:0}.tablewrap{overflow:auto;max-height:310px}table{width:100%;border-collapse:collapse}th,td{padding:8px 7px;text-align:left;border-bottom:1px solid #1d2c40;white-space:nowrap}th{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}button,input,select{border:1px solid var(--line);background:#0a1420;color:var(--text);border-radius:8px;padding:8px 9px}button{cursor:pointer;font-weight:650}button.primary{border:0;background:linear-gradient(135deg,#247fff,#38bdf8)}button.danger{border-color:#713642;color:var(--red)}button:disabled{opacity:.45}.field{display:flex;flex-direction:column;gap:4px;flex:1;min-width:115px}.field label{font-size:10px;color:var(--muted)}.two{display:grid;grid-template-columns:1fr 1fr;gap:8px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.notice{font-size:11px;padding:8px 10px;border-radius:8px;background:#102033;border:1px solid #24415f;color:#aec4dd}.log{font:11px ui-monospace,SFMono-Regular,Menlo,monospace}.empty{padding:18px;text-align:center;color:var(--muted)}.up{color:var(--green)}.down{color:var(--red)}.auth{min-width:310px}.msg{min-height:18px;margin-top:6px;color:var(--muted);font-size:11px}.divider{height:1px;background:var(--line);margin:12px 0}@media(max-width:1200px){.metric{grid-column:span 4}.span4,.span5,.span6,.span7,.span8{grid-column:span 12}}@media(max-width:700px){.shell{padding:9px}.metric{grid-column:span 6}.top{align-items:flex-start;flex-direction:column}.two,.three{grid-template-columns:1fr}.auth{min-width:0;width:100%}}
</style>
</head>
<body><div class="shell">
<div class="top"><div class="brand"><div class="logo">ZK</div><div><h1>zksato Trading Control</h1><div class="sub tiny">Risk-first SET / TFEX operations · port 9569</div></div></div><div class="status"><span id="mode" class="pill">mode</span><span id="botState" class="pill">bot stopped</span><span id="authState" class="pill">auth unknown</span><span id="clock" class="pill"></span></div></div>
<div class="card span12" style="margin-bottom:12px"><div class="head"><h2>Operator Session</h2><span class="tiny muted">Key stays in browser session memory only; never hard-code broker or API secrets.</span></div><div class="row"><input id="apiKey" class="auth" type="password" placeholder="X-API-Key / Bearer key"><button onclick="saveKey()">Use key</button><button onclick="clearKey()">Clear</button><button onclick="whoami()">Check role</button><span id="who" class="tiny muted"></span></div></div>
<div class="grid">
<div class="card metric"><div class="k">EQUITY</div><div id="equity" class="v">—</div><div id="daily" class="tiny muted">—</div></div>
<div class="card metric"><div class="k">CASH</div><div id="cash" class="v">—</div></div>
<div class="card metric"><div class="k">MARKET VALUE</div><div id="marketValue" class="v">—</div></div>
<div class="card metric"><div class="k">UNREALIZED P/L</div><div id="upnl" class="v">—</div></div>
<div class="card metric"><div class="k">ORDERS</div><div id="orderCount" class="v">0</div></div>
<div class="card metric"><div class="k">SIGNALS</div><div id="signalCount" class="v">0</div></div>

<div class="card span8"><div class="head"><h2>Market Watch</h2><div class="row"><button onclick="feed('/v1/market/demo/start')">Demo start</button><button onclick="feed('/v1/market/demo/stop')">Demo stop</button><button onclick="feed('/v1/market/settrade/start')">Settrade start</button><button onclick="feed('/v1/market/settrade/stop')">Settrade stop</button><button onclick="refresh()">Refresh</button></div></div><div class="tablewrap"><table><thead><tr><th>Symbol</th><th>Last</th><th>Change</th><th>Bid</th><th>Offer</th><th>Volume</th><th>Age</th></tr></thead><tbody id="marketRows"></tbody></table></div></div>
<div class="card span4"><div class="head"><h2>Scanner</h2><button onclick="loadScanner()">Scan</button></div><div id="scanner" class="tablewrap"></div></div>

<div class="card span5"><div class="head"><h2>Automation</h2><span class="tiny muted">live auto-execution is hard blocked</span></div><div class="notice">Paper and Settrade UAT may automate. Live mode is signal-only; live equity mutation requires a one-time exact-intent approval.</div><div class="row"><div class="field"><label>Symbols</label><input id="symbols" value="AOT,PTT,CPALL,KBANK,ADVANC"></div></div><div class="two"><div class="field"><label>Strategy</label><select id="strategy"><option value="ema_cross">EMA Cross</option><option value="rsi_reversion">RSI Reversion</option><option value="breakout">Breakout</option></select></div><div class="field"><label>Order size</label><input id="size" type="number" value="100" min="1"></div><div class="field"><label>Stop loss %</label><input id="sl" type="number" value="2" step="0.1"></div><div class="field"><label>Take profit %</label><input id="tp" type="number" value="4" step="0.1"></div></div><div class="row"><label><input id="auto" type="checkbox" checked> auto execute</label><button class="primary" onclick="startBot()">Start</button><button class="danger" onclick="bot('/v1/bot/stop')">Stop</button><button onclick="bot('/v1/bot/tick')">Tick</button></div><div id="botMsg" class="msg"></div></div>

<div class="card span7"><div class="head"><h2>Equity Order + Live Approval</h2><button onclick="reconcile()">Reconcile broker</button></div><div class="three"><div class="field"><label>Symbol</label><input id="osymbol" value="AOT"></div><div class="field"><label>Side</label><select id="oside"><option value="buy">Buy</option><option value="sell">Sell</option></select></div><div class="field"><label>Quantity</label><input id="oqty" type="number" value="100"></div><div class="field"><label>Type</label><select id="otype"><option value="market">Market</option><option value="limit">Limit</option></select></div><div class="field"><label>Limit price</label><input id="oprice" type="number" step="0.01"></div><div class="field"><label>Stop loss</label><input id="ostop" type="number" step="0.01"></div><div class="field"><label>Take profit</label><input id="otake" type="number" step="0.01"></div><div class="field"><label>Live approval ID</label><input id="approvalId" placeholder="created by risk_admin"></div></div><div class="row"><button onclick="preflight()">Server risk preflight</button><button onclick="createApproval()">Create live approval</button><button class="primary" onclick="manualOrder()">Submit exact order</button><button onclick="resetIntent()">Reset prepared intent</button></div><div class="notice">For four-eyes live flow: prepare with a risk-admin key, create approval, switch to a distinct order-approver key, then submit. The approval binds the exact symbol/side/quantity/type/price/stops/client ID and is consumed once.</div><div id="orderMsg" class="msg"></div></div>

<div class="card span5"><div class="head"><h2>Portfolio</h2></div><div class="tablewrap"><table><thead><tr><th>Symbol</th><th>Qty</th><th>Avg</th><th>Last</th><th>Value</th><th>P/L</th></tr></thead><tbody id="portfolioRows"></tbody></table></div></div>
<div class="card span7"><div class="head"><h2>Orders</h2></div><div class="tablewrap"><table><thead><tr><th>Time</th><th>Symbol</th><th>Side</th><th>Qty</th><th>Fill</th><th>Price</th><th>Status</th><th>Source</th></tr></thead><tbody id="orderRows"></tbody></table></div></div>

<div class="card span6"><div class="head"><h2>TFEX Control (UAT mutation only)</h2><div class="row"><button onclick="tfexRead('account')">Account</button><button onclick="tfexRead('portfolio')">Portfolio</button><button onclick="tfexRead('orders')">Orders</button></div></div><div class="three"><div class="field"><label>Contract</label><input id="tsymbol" value="S50Z26"></div><div class="field"><label>Side</label><select id="tside"><option>LONG</option><option>SHORT</option></select></div><div class="field"><label>Position</label><select id="tposition"><option>OPEN</option><option>CLOSE</option><option>AUTO</option></select></div><div class="field"><label>Volume</label><input id="tvolume" type="number" value="1" min="1"></div><div class="field"><label>Limit price</label><input id="tprice" type="number" value="900" step="0.1"></div></div><div class="row"><button onclick="tfexPreflight()">Trusted TFEX preflight</button><button class="primary" onclick="tfexUatOrder()">Submit UAT order</button></div><div class="notice">No live TFEX mutation endpoint exists in this revision. Server derives portfolio/margin/market-data risk context before UAT mutation.</div><pre id="tfexOut" class="log tablewrap"></pre></div>

<div class="card span6"><div class="head"><h2>Signals</h2></div><div id="signals" class="tablewrap"></div><div class="divider"></div><div class="head"><h2>Price Alerts</h2></div><div class="row"><input id="asymbol" value="AOT" style="width:85px"><select id="aop"><option value="gte">≥</option><option value="lte">≤</option></select><input id="aprice" type="number" step="0.01" placeholder="price" style="width:110px"><button onclick="addAlert()">Add</button></div><div id="alerts"></div></div>

<div class="card span12"><div class="head"><h2>Audit Trail</h2><span class="tiny muted">broker credentials and approval secrets are never displayed</span></div><div id="audit" class="tablewrap log"></div></div>
</div></div>
<script>
const money=n=>new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB',maximumFractionDigits:2}).format(Number(n||0));const num=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(Number(n||0));const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));let snapshot=null;let preparedIntent=null;let sessionKey=sessionStorage.getItem('zksato_api_key')||'';document.getElementById('apiKey').value=sessionKey;
function headers(extra={}){const h={...extra};if(sessionKey)h['X-API-Key']=sessionKey;return h}async function api(path,opt={}){opt.headers=headers(opt.headers||{});const r=await fetch(path,opt);let body=null;try{body=await r.json()}catch{}if(!r.ok)throw new Error(body?.detail?JSON.stringify(body.detail):`HTTP ${r.status}`);return body}function jsonOpt(method,body,extra={}){return{method,headers:{'Content-Type':'application/json',...extra},body:JSON.stringify(body)}}function cls(n){return Number(n)>=0?'up':'down'}function time(s){return s?new Date(s).toLocaleTimeString():''}function age(s){if(!s)return'—';return Math.max(0,(Date.now()-new Date(s).getTime())/1000).toFixed(1)+'s'}function val(id){return document.getElementById(id).value}function nval(id){const v=val(id);return v===''?null:Number(v)}function message(id,text,bad=false){const el=document.getElementById(id);el.textContent=text;el.className='msg '+(bad?'bad':'good')}
function saveKey(){sessionKey=val('apiKey').trim();if(sessionKey)sessionStorage.setItem('zksato_api_key',sessionKey);else sessionStorage.removeItem('zksato_api_key');whoami();refresh()}function clearKey(){sessionKey='';sessionStorage.removeItem('zksato_api_key');document.getElementById('apiKey').value='';document.getElementById('who').textContent='';document.getElementById('authState').textContent='auth cleared'}async function whoami(){try{const me=await api('/v1/auth/me');document.getElementById('who').textContent=`${me.role} · ${me.subject}`;document.getElementById('authState').textContent=me.role}catch(e){document.getElementById('authState').textContent='auth required';document.getElementById('who').textContent=e.message}}
async function refresh(){try{snapshot=await api('/v1/dashboard');render(snapshot);loadScanner()}catch(e){document.getElementById('authState').textContent='API '+e.message}}
function render(s){document.getElementById('mode').textContent=`${s.mode.toUpperCase()} · ${s.kill_switch?'KILL SWITCH':'risk active'}`;document.getElementById('mode').className='pill '+(s.kill_switch?'bad':'good');document.getElementById('botState').textContent='bot '+s.bot.state;document.getElementById('equity').textContent=money(s.portfolio.equity);document.getElementById('cash').textContent=money(s.portfolio.cash);document.getElementById('marketValue').textContent=money(s.portfolio.market_value);document.getElementById('upnl').textContent=money(s.portfolio.unrealized_pnl);document.getElementById('upnl').className='v '+cls(s.portfolio.unrealized_pnl);document.getElementById('daily').textContent=`Daily ${money(s.portfolio.daily_pnl)}`;document.getElementById('daily').className='tiny '+cls(s.portfolio.daily_pnl);document.getElementById('orderCount').textContent=s.orders.length;document.getElementById('signalCount').textContent=s.signals.length;renderMarket(s.quotes);renderPortfolio(s.portfolio.positions);renderOrders(s.orders);renderSignals(s.signals);renderAlerts(s.alerts);renderAudit(s.audit)}
function renderMarket(rows){document.getElementById('marketRows').innerHTML=rows.length?rows.map(q=>`<tr><td><b>${esc(q.symbol)}</b></td><td>${num(q.last)}</td><td class="${cls(q.change_pct)}">${num(q.change_pct)}%</td><td>${num(q.bid)}</td><td>${num(q.offer)}</td><td>${num(q.volume)}</td><td class="muted">${age(q.timestamp)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">No quotes</td></tr>'}function renderPortfolio(rows){document.getElementById('portfolioRows').innerHTML=rows.length?rows.map(p=>`<tr><td><b>${esc(p.symbol)}</b></td><td>${num(p.quantity)}</td><td>${num(p.average_price)}</td><td>${num(p.market_price)}</td><td>${money(p.market_value)}</td><td class="${cls(p.unrealized_pnl)}">${money(p.unrealized_pnl)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No positions</td></tr>'}function renderOrders(rows){document.getElementById('orderRows').innerHTML=rows.slice(0,80).map(o=>`<tr><td>${time(o.created_at)}</td><td><b>${esc(o.symbol)}</b></td><td class="${o.side==='buy'?'up':'down'}">${esc(o.side).toUpperCase()}</td><td>${num(o.quantity)}</td><td>${num(o.filled_quantity)}</td><td>${num(o.average_fill_price||o.price)}</td><td>${esc(o.status)}</td><td class="muted">${esc(o.source)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No orders</td></tr>'}function renderSignals(rows){document.getElementById('signals').innerHTML=rows.slice(0,30).map(x=>`<div style="padding:8px;border-bottom:1px solid #1d2c40"><b class="${x.action==='buy'?'up':'down'}">${esc(x.action).toUpperCase()}</b> ${esc(x.symbol)} <span class="muted">${esc(x.strategy)}</span><div class="tiny muted">${esc(x.reason)} · ${time(x.timestamp)}</div></div>`).join('')||'<div class="empty">No signals</div>'}function renderAlerts(rows){document.getElementById('alerts').innerHTML=rows.map(a=>`<div class="row"><span>${esc(a.symbol)} ${a.operator==='gte'?'≥':'≤'} ${num(a.price)}</span><span class="tiny ${a.enabled?'good':'muted'}">${a.enabled?'armed':'triggered'}</span><button onclick="deleteAlert('${esc(a.id)}')">×</button></div>`).join('')||'<div class="empty">No alerts</div>'}function renderAudit(rows){document.getElementById('audit').innerHTML=rows.slice(0,80).map(a=>`<div style="padding:7px;border-bottom:1px solid #1d2c40"><span class="muted">${time(a.timestamp)}</span> <b>${esc(a.event_type)}</b> ${esc(a.message)}</div>`).join('')||'<div class="empty">No audit events</div>'}
async function loadScanner(){try{const rows=await api('/v1/scanner?limit=12');document.getElementById('scanner').innerHTML=rows.map(x=>`<div style="padding:8px;border-bottom:1px solid #1d2c40"><b>${esc(x.symbol)}</b> ${num(x.last)} <span class="${cls(x.change_pct)}">${num(x.change_pct)}%</span><div class="tiny muted">score ${num(x.score)} · ${x.reasons.map(esc).join(' · ')}</div></div>`).join('')||'<div class="empty">No scanner matches</div>'}catch(e){document.getElementById('scanner').textContent=e.message}}
async function feed(path){try{await api(path,{method:'POST'});await refresh()}catch(e){alert(e.message)}}async function bot(path){try{await api(path,{method:'POST'});await refresh()}catch(e){message('botMsg',e.message,true)}}async function startBot(){const body={symbols:val('symbols').split(',').map(x=>x.trim()).filter(Boolean),strategy:{name:val('strategy')},order_size:Number(val('size')),stop_loss_pct:Number(val('sl')),take_profit_pct:Number(val('tp')),auto_execute:document.getElementById('auto').checked,cooldown_seconds:60};try{await api('/v1/bot/start',jsonOpt('POST',body));message('botMsg','Bot started');await refresh()}catch(e){message('botMsg',e.message,true)}}
function buildIntent(){const side=val('oside');const type=val('otype');const intent={symbol:val('osymbol').trim().toUpperCase(),side,quantity:Number(val('oqty')),order_type:type,client_order_id:'dashboard-'+crypto.randomUUID(),source:'dashboard'};const price=nval('oprice'),stop=nval('ostop'),take=nval('otake');if(type==='limit'&&price!==null)intent.price=price;if(side==='buy'&&stop!==null)intent.stop_loss=stop;if(side==='buy'&&take!==null)intent.take_profit=take;return intent}function resetIntent(){preparedIntent=null;document.getElementById('approvalId').value='';message('orderMsg','Prepared intent cleared')}
async function preflight(){const intent=buildIntent();try{const d=await api('/v1/risk/preflight',jsonOpt('POST',intent));message('orderMsg',d.approved?`APPROVED · notional ${num(d.estimated_notional)}`:`REJECTED · ${d.reasons.join('; ')}`,!d.approved)}catch(e){message('orderMsg',e.message,true)}}async function createApproval(){preparedIntent=buildIntent();try{const a=await api('/v1/live-approvals',jsonOpt('POST',{intent:preparedIntent,ttl_seconds:120}));document.getElementById('approvalId').value=a.id;message('orderMsg',`Approval ${a.id} created. Switch to a distinct order-approver key before submit.`)}catch(e){preparedIntent=null;message('orderMsg',e.message,true)}}async function manualOrder(){const approval=val('approvalId').trim();const intent=preparedIntent||buildIntent();try{const extra=approval?{'X-Live-Approval-Id':approval}:{};const o=await api('/v1/orders',jsonOpt('POST',{intent,risk:{}},extra));message('orderMsg',`${o.status}: ${o.side.toUpperCase()} ${o.quantity} ${o.symbol}`);preparedIntent=null;document.getElementById('approvalId').value='';await refresh()}catch(e){message('orderMsg',e.message,true)}}async function reconcile(){try{const r=await api('/v1/reconcile',{method:'POST'});message('orderMsg',`Reconciled: ${r.examined_remote} remote, ${r.updated} updated, ${r.unresolved_order_ids.length} unresolved`);await refresh()}catch(e){message('orderMsg',e.message,true)}}
async function addAlert(){try{await api('/v1/alerts',jsonOpt('POST',{symbol:val('asymbol'),operator:val('aop'),price:Number(val('aprice')),enabled:true}));await refresh()}catch(e){alert(e.message)}}async function deleteAlert(id){try{await api('/v1/alerts/'+encodeURIComponent(id),{method:'DELETE'});await refresh()}catch(e){alert(e.message)}}
function tfexIntent(){return{symbol:val('tsymbol').trim().toUpperCase(),side:val('tside'),position:val('tposition'),volume:Number(val('tvolume')),price:Number(val('tprice')),price_type:'LIMIT',validity_type:'GOOD_TILL_DAY',stop_condition:'',stop_price:0,stop_symbol:'',bypass_warning:false}}async function tfexRead(kind){try{const r=await api('/v1/tfex/'+kind);document.getElementById('tfexOut').textContent=JSON.stringify(r,null,2)}catch(e){document.getElementById('tfexOut').textContent=e.message}}async function tfexPreflight(){try{const r=await api('/v1/tfex/risk/preflight',jsonOpt('POST',tfexIntent()));document.getElementById('tfexOut').textContent=JSON.stringify(r,null,2)}catch(e){document.getElementById('tfexOut').textContent=e.message}}async function tfexUatOrder(){try{const r=await api('/v1/tfex/orders/uat',jsonOpt('POST',{intent:tfexIntent(),risk:{}}));document.getElementById('tfexOut').textContent=JSON.stringify(r,null,2);await refresh()}catch(e){document.getElementById('tfexOut').textContent=e.message}}
setInterval(()=>document.getElementById('clock').textContent=new Date().toLocaleString(),1000);setInterval(refresh,3000);whoami();refresh();
</script></body></html>"""
